def check_k_elements(tuple_list, k):
    if k <= 0:
        return False
    elements_found = set()
    for tup in tuple_list:
        for elem in tup:
            if 1 <= elem <= k:
                elements_found.add(elem)
            if len(elements_found) == k:
                return True
    return len(elements_found) == k

def sub_list(list1, list2):
    if len(list1) != len(list2):
        raise ValueError("Input lists must be of the same length.")

    def check_numeric(x):
        return isinstance(x, (int, float))

    if not all(map(check_numeric, list1)) or not all(map(check_numeric, list2)):
        raise TypeError("All elements must be numeric (int or float).")

    return list(map(lambda x, y: x - y, list1, list2))

