def find_lists(t):
    def count_lists(obj):
        if isinstance(obj, list):
            # Count this list itself
            count = 1
            for e in obj:
                if isinstance(e, list):
                    count += count_lists(e)
                elif isinstance(e, tuple):
                    count += count_lists(e)
            return count
        elif isinstance(obj, tuple):
            # Recurse into tuple elements but don't count tuple as list
            return sum(count_lists(e) for e in obj)
        else:
            return 0

