def second_smallest(lst):
    if len(lst) < 2:
        raise ValueError("List must contain at least two elements.")
    unique_vals = set(lst)
    if len(unique_vals) < 2:
        raise ValueError("No distinct second smallest number found.")
    sorted_vals = sorted(unique_vals)
    return sorted_vals[1]

def is_decimal(s: str) -> bool:
    # Check if the string matches a pattern of optional sign, digits, decimal point, exactly two digits
    if not isinstance(s, str):
        return False
    parts = s.split('.')
    if len(parts) != 2:
        return False
    integer_part, decimal_part = parts
    # integer part can be signed, so handle leading sign
    if integer_part.startswith(('+', '-')):
        integer_part = integer_part[1:]
    if not integer_part.isdigit():
        return False
    if len(decimal_part) != 2 or not decimal_part.isdigit():
        return False
    return True

def is_Two_Alter(s):
    if len(s) < 2:
        return False

    distinct_chars = set(s)
    if len(distinct_chars) != 2:
        return False

    # Check characters alternate strictly
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            return False
    return True

def max_sub_array_sum(arr):
    if not arr:
        return 0
    max_ending_here = max_so_far = arr[0]
    for x in arr[1:]:
        max_ending_here = max(x, max_ending_here + x)
        max_so_far = max(max_so_far, max_ending_here)
    return max_so_far

def len_log(words):
    if not words:
        return 0
    return max(len(word) for word in words)

def double_the_difference(lst):
    total = 0
    for x in lst:
        if isinstance(x, int) and x > 0 and x % 2 == 1:
            total += x * x
    return total

def count_nums(arr):
    count = 0
    for x in arr:
        if not isinstance(x, int):
            continue
        s = str(abs(x))
        digits = [int(d) for d in s]
        if x < 0:
            digits[0] = -digits[0]
        if sum(digits) > 0:
            count += 1
    return count

