def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime.
    >>> largest_prime_factor(13195)
    29
    >>> largest_prime_factor(2048)
    2
    """
    if n <= 1:
        raise ValueError("Input must be greater than 1")

    # Helper function to check if a number is prime
    def is_prime(x):
        if x <= 1:
            return False
        if x <= 3:
            return True
        if x % 2 == 0 or x % 3 == 0:
            return False
        i = 5
        while i * i <= x:
            if x % i == 0 or x % (i + 2) == 0:
                return False
            i += 6
        return True

    # If n is prime, raise error per specification
    if is_prime(n):
        raise ValueError("Input must not be prime")

    largest_factor = None
    temp = n

    # Check divisibility by 2
    while temp % 2 == 0:
        largest_factor = 2
        temp //= 2

    # Check odd factors from 3 upwards
    factor = 3
    while factor * factor <= temp:
        while temp % factor == 0:
            largest_factor = factor
            temp //= factor
        factor += 2

    # If temp > 1, it is a prime factor larger than any found so far
    if temp > 1:
        largest_factor = temp

    if largest_factor is None or largest_factor == n:
        # This should not happen given assumptions, but just in case
        raise ValueError("No prime factor found other than n itself")

    return largest_factor

def cycpattern_check(a, b):
    if len(b) > len(a):
        return False

    # Generate all rotations of b
    # A neat trick: b rotated by k is b[k:] + b[:k]
    for i in range(len(b)):
        rotated = b[i:] + b[:i]
        if rotated in a:
            return True
    return False

