def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.strip().split()
    result = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif char == ')':
                current_depth -= 1
        result.append(max_depth)
    return result

def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    prime_length_words = [w for w in words if is_prime(len(w))]

    # According to the example, we want to return all words with prime length
    # that do NOT contain any other prime-length word as a substring.
    # So, for each prime-length word, check if any other prime-length word is a substring of it.
    result = []
    for w in prime_length_words:
        # Check if any other prime length word is a substring of w, excluding itself
        if not any(other != w and other in w for other in prime_length_words):
            result.append(w)

    return " ".join(result)

